package fable.hideseek.imba.game;
import fable.hideseek.imba.config.OverlayBarrierConfig;import net.minecraft.entity.Entity;import net.minecraft.util.math.Box;import net.minecraft.util.math.Vec3d;import java.util.ArrayList;import java.util.List;
public final class OverlayBarrierRuntime{private static final List<OverlayBarrierConfig.Entry> CLIENT_ENTRIES=new ArrayList<>();private OverlayBarrierRuntime(){}public static void replaceClient(List<OverlayBarrierConfig.Entry> entries){CLIENT_ENTRIES.clear();CLIENT_ENTRIES.addAll(entries);}public static List<OverlayBarrierConfig.Entry> clientSnapshot(){return List.copyOf(CLIENT_ENTRIES);}public static Vec3d clip(Entity entity,Vec3d vanillaMovement){if(entity==null||vanillaMovement==null||entity.noClip||vanillaMovement.lengthSquared()<1.0E-14D)return vanillaMovement;Box box=entity.getBoundingBox();Box query=box.stretch(vanillaMovement).expand(1.0E-7D);List<Box> obstacles=entity.getWorld().isClient?clientBoxes(entity,query):OverlayBarrierConfig.boxes(entity.getWorld(),query);if(obstacles.isEmpty())return vanillaMovement;double dy=clipY(box,vanillaMovement.y,obstacles);if(dy!=0.0D)box=box.offset(0.0D,dy,0.0D);double dx=clipX(box,vanillaMovement.x,obstacles);if(dx!=0.0D)box=box.offset(dx,0.0D,0.0D);double dz=clipZ(box,vanillaMovement.z,obstacles);return new Vec3d(dx,dy,dz);}private static List<Box> clientBoxes(Entity entity,Box query){String world=entity.getWorld().getRegistryKey().getValue().toString();List<Box> result=new ArrayList<>();for(var entry:CLIENT_ENTRIES){if(!world.equals(entry.world))continue;Box box=new Box(entry.x,entry.y,entry.z,entry.x+1.0D,entry.y+1.0D,entry.z+1.0D);if(box.intersects(query))result.add(box);}return result;}private static double clipY(Box mover,double amount,List<Box> obstacles){double result=amount;for(Box o:obstacles){if(!overlap(mover.minX,mover.maxX,o.minX,o.maxX)||!overlap(mover.minZ,mover.maxZ,o.minZ,o.maxZ))continue;if(result>0.0D&&mover.maxY<=o.minY)result=Math.min(result,o.minY-mover.maxY);else if(result<0.0D&&mover.minY>=o.maxY)result=Math.max(result,o.maxY-mover.minY);}return result;}private static double clipX(Box mover,double amount,List<Box> obstacles){double result=amount;for(Box o:obstacles){if(!overlap(mover.minY,mover.maxY,o.minY,o.maxY)||!overlap(mover.minZ,mover.maxZ,o.minZ,o.maxZ))continue;if(result>0.0D&&mover.maxX<=o.minX)result=Math.min(result,o.minX-mover.maxX);else if(result<0.0D&&mover.minX>=o.maxX)result=Math.max(result,o.maxX-mover.minX);}return result;}private static double clipZ(Box mover,double amount,List<Box> obstacles){double result=amount;for(Box o:obstacles){if(!overlap(mover.minX,mover.maxX,o.minX,o.maxX)||!overlap(mover.minY,mover.maxY,o.minY,o.maxY))continue;if(result>0.0D&&mover.maxZ<=o.minZ)result=Math.min(result,o.minZ-mover.maxZ);else if(result<0.0D&&mover.minZ>=o.maxZ)result=Math.max(result,o.maxZ-mover.minZ);}return result;}private static boolean overlap(double a0,double a1,double b0,double b1){return a1>b0+1.0E-9D&&a0<b1-1.0E-9D;}}
